<?php require_once 'auth_check.php';require_once '../koneksi.php';require_once 'app_helpers.php';if(!in_array($_SESSION['kode_role'],['ADMIN','OPERATOR_PRODI'],true)){http_response_code(403);die('403');}if($_SERVER['REQUEST_METHOD']!=='POST')redirect_to('mahasiswa.php');csrf_verify();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);if(!$id)redirect_to('mahasiswa.php');$st=mysqli_prepare($koneksi,"SELECT * FROM mahasiswa WHERE id_mahasiswa=?");mysqli_stmt_bind_param($st,'i',$id);mysqli_stmt_execute($st);$old=mysqli_fetch_assoc(mysqli_stmt_get_result($st));mysqli_stmt_close($st);if(!$old)redirect_to('mahasiswa.php');if($_SESSION['kode_role']==='OPERATOR_PRODI'&&(int)$old['id_program_studi']!==(int)$_SESSION['id_program_studi']){http_response_code(403);die('403 - Data di luar kewenangan.');}$st=mysqli_prepare($koneksi,"DELETE FROM mahasiswa WHERE id_mahasiswa=?");mysqli_stmt_bind_param($st,'i',$id);if(mysqli_stmt_execute($st)){audit_log($koneksi,(int)$_SESSION['id_pengguna'],'mahasiswa',(string)$id,'DELETE',$old,null);flash('success','Data mahasiswa berhasil dihapus.');}else flash('error','Gagal menghapus data mahasiswa.');mysqli_stmt_close($st);redirect_to('mahasiswa.php');